CREATE TABLE schema_version (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), version INTEGER NOT NULL);
INSERT INTO schema_version VALUES (1, 1);
CREATE TABLE state (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), label TEXT NOT NULL, value INTEGER NOT NULL CHECK (value BETWEEN -9007199254740991 AND 9007199254740991), revision INTEGER NOT NULL CHECK (revision BETWEEN 0 AND 9007199254740991));
CREATE TABLE receipts (idempotency_key TEXT PRIMARY KEY, intent_digest TEXT NOT NULL, label TEXT NOT NULL, value INTEGER NOT NULL CHECK (value BETWEEN -9007199254740991 AND 9007199254740991), revision INTEGER NOT NULL CHECK (revision BETWEEN 1 AND 9007199254740991), receipt_id TEXT NOT NULL UNIQUE);
